229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        normalizeAddress(ownerFieldsDto);
237	        currentOwner.setAddress(addressFor(ownerFieldsDto));
238	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
239	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
240	        currentOwner.setCity(ownerFieldsDto.getCity());
241	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
242	        currentOwner.setLastName(ownerFieldsDto.getLastName());
243	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
244	        normalizeEmail(ownerFieldsDto);
245	        currentOwner.setEmail(ownerFieldsDto.getEmail());
246	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
247	        this.clinicService.saveOwner(currentOwner);
248	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
249	    }
