328	    /**
329	     * The owner's current primary identifier, as carried on the {@link OwnerCreatedEvent} audit event.
330	     * Today an owner is keyed by its {@code customerCode}; when that identifier is later unified into
331	     * the {@code memberId}, this single accessor changes to return the memberId and the emitted event
332	     * carries it in place of the customer code, with no other call site affected.
333	     *
334	     * @param owner the freshly created owner, already stamped with its {@code customerCode}
335	     * @return the owner's current primary identifier
336	     */
337	    private String primaryIdentifier(Owner owner) {
338	        return owner.getCustomerCode();
339	    }
340	
341	    /**
342	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
343	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
344	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
345	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
346	     *
347	     * @return the non-blank idempotency key, or {@code null} when none was supplied
348	     */
349	    private String idempotencyKey() {
350	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
351	            return null;
352	        }
353	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
354	        return isBlank(key) ? null : key.trim();
355	    }
356	
357	    /**
358	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
359	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
360	     * the request body already rejects null and empty values, but permits whitespace-only strings
361	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
362	     * that gap so every required field must carry a non-blank value.
363	     *
364	     * @param ownerFieldsDto the submitted owner fields
365	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
366	     */
367	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
368	        List<String> missing = new ArrayList<>();
369	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
370	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
371	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
372	            missing.add("address");
373	        }
374	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
375	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
376	        if (!missing.isEmpty()) {
377	            throw new InvalidOwnerFieldsException(missing);
378	        }
379	    }
380	
381	    /**
382	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
383	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
384	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
385	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
386	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
387	     * {@link PostcodeValidator}.
388	     *
389	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
390	     *                       {@link #rejectBlankOwnerFields} having already run)
391	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
392	     */
393	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
394	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
395	            throw new InvalidOwnerFieldsException(List.of("postcode"));
396	        }
397	    }
398	
399	    private void addIfBlank(List<String> missing, String fieldName, String value) {
400	        if (isBlank(value)) {
401	            missing.add(fieldName);
402	        }
403	    }
404	
405	    private boolean isBlank(String value) {
406	        return value == null || value.isBlank();
407	    }
408	
409	    /**
410	     * Normalizes the submitted address on create to its canonical form (see
411	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
412	     * stored and returned, and the form every later address comparison (the required-field check,
413	     * household duplicate detection and the shared household id) is judged on. The structured fields
414	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
415	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
416	     * derived from them when a structured {@code addressLine1} is present, falling back to the
417	     * normalized flat {@code address} otherwise. Any absent field is left absent so
418	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
419	     * after normalization likewise reduces to the empty string and is rejected there.
420	     *
421	     * @param ownerFieldsDto the submitted owner fields
422	     */
423	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
424	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
425	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
426	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
427	        ownerFieldsDto.setAddressLine1(addressLine1);
428	        ownerFieldsDto.setAddressLine2(addressLine2);
429	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
430	    }
431	
432	    /**
433	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
434	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
435	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
436	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
437	     * is the single value every later reader of the address (the required-field check, household
438	     * duplicate detection and the shared household id) is judged on.
439	     *
440	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
441	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
442	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
443	     * @return the composed flat address, or {@code null} when no address form was supplied
444	     */
445	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
446	        if (isBlank(addressLine1)) {
447	            return flatAddress;
448	        }
449	        if (isBlank(addressLine2)) {
450	            return addressLine1;
451	        }
452	        return addressLine1 + " " + addressLine2;
453	    }
454	
455	    /**
456	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
457	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
458	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
459	     * {@code 400 Bad Request}.
460	     *
461	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
462	     *                       {@link #rejectBlankOwnerFields} having already run)
463	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
464	     */
465	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
466	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
467	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
468	        ownerFieldsDto.setTelephone(normalized);
469	    }
470	
471	    /**
472	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
473	     * untouched (email is optional). When present it is reduced to its canonical form (see
474	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
475	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
476	     *
477	     * @param ownerFieldsDto the submitted owner fields
478	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
479	     *                                     or its domain is on the disposable-domain blocklist
480	     */
481	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
482	        String email = ownerFieldsDto.getEmail();
483	        if (email == null || email.isBlank()) {
484	            return;
485	        }
486	        String normalized = EmailNormalizer.normalize(email)
487	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
488	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
489	            throw new InvalidOwnerFieldsException(List.of("email"));
490	        }
491	        ownerFieldsDto.setEmail(normalized);
492	    }
493	
494	    /**
495	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
496	     * duplicate detection is now expressed through the single derived {@code identityKey}
497	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
498	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
499	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
500	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
501	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
502	     * carry different telephones have different keys and are both allowed (they are instead recorded as
503	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
504	     * longer makes a duplicate.
505	     *
506	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
507	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
508	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
509	     */
510	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
511	        String identityKey = OwnerIdentity.identityKey(
512	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
513	        boolean inUse = activeOwners().stream()
514	            .map(OwnerIdentity::identityKey)
515	            .anyMatch(identityKey::equals);
516	        if (inUse) {
517	            throw new DuplicateOwnerIdentityException(identityKey);
518	        }
519	    }
520	
521	    /**
522	     * The owners considered by duplicate detection: every persisted owner except those flagged
523	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
524	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
525	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
526	     * alone. Only owners already persisted (before this create) are included.
527	     *
528	     * @return the non-deleted owners currently persisted
529	     */
530	    private List<Owner> activeOwners() {
531	        return this.clinicService.findAllOwners().stream()
532	            .filter(owner -> !owner.isDeleted())
533	            .toList();
534	    }
535	
536	    /**
537	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
538	     * both match the submitted values, compared case-insensitively. The count reflects only owners
539	     * already persisted at the time of the create, so the owner being created is never included.
540	     *
541	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
542	     *                  having already run)
543	     * @param lastName  the submitted last name (non-blank here)
544	     * @return the number of existing owners sharing the same first and last name
545	     */
546	    private int countNamesakes(String firstName, String lastName) {
547	        return (int) this.clinicService.findAllOwners().stream()
548	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
549	                && lastName.equalsIgnoreCase(owner.getLastName()))
550	            .count();
551	    }
552	
553	    /**
554	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
555	     * whose stored {@code householdId} equals the value derived for the owner being created. The
556	     * count reflects only owners already persisted at the time of the create, so the owner being
557	     * created is never included; callers add one to obtain the household size after this create.
558	     *
559	     * @param householdId the household identifier derived for the owner being created (see
560	     *                    {@link HouseholdNormalizer#toHouseholdId})
561	     * @return the number of existing owners already sharing that household
562	     */
563	    private int countHouseholdMembers(String householdId) {
564	        return householdMembers(householdId).size();
565	    }
566	
567	    /**
568	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
569	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
570	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
571	     * created is never among them.
572	     *
573	     * @param householdId the household identifier derived for the owner being created (see
574	     *                    {@link HouseholdNormalizer#toHouseholdId})
575	     * @return the existing owners already sharing that household (empty when {@code householdId} is
576	     *         {@code null})
577	     */
578	    private List<Owner> householdMembers(String householdId) {
579	        if (householdId == null) {
580	            return List.of();
581	        }
582	        return this.clinicService.findAllOwners().stream()
583	            .filter(member -> householdId.equals(member.getHouseholdId()))
584	            .toList();
585	    }
586	
587	    /**
588	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
589	     * {@code membershipLevel} among their existing household members. The owner's own level is the
590	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
591	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
592	     * owner's own level is returned unchanged.
593	     *
594	     * @param owner the owner being created, already stamped with its household id and size
595	     * @return the (possibly capped) membership level to stamp on the owner
596	     */
597	    private int cappedMembershipLevel(Owner owner) {
598	        int ownLevel = this.ownerMapper.membershipLevel(owner);
599	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
600	            .mapToInt(this.ownerMapper::membershipLevel)
601	            .max();
602	        return maxHouseholdLevel.isPresent()
603	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
604	            : ownLevel;
605	    }
606	
607	    /**
608	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
609	     * owner with an address taken from the request, so routing that through this single method keeps the
610	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
611	     * household id.
612	     *
613	     * @param ownerFieldsDto the submitted owner fields
614	     * @return the address to store on the owner
615	     */
616	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
617	        return ownerFieldsDto.getAddress();
618	    }
619	
620	    /**
621	     * Derives the household id an owner should carry from its submitted fields (see
622	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
623	     * household id, so routing them through this single method keeps them agreed on which of the
624	     * owner's fields key the household.
625	     *
626	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
627	     *                       {@link #rejectBlankOwnerFields} having already run on create)
628	     * @return the owner's household id
629	     */
630	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
631	        return HouseholdNormalizer.toHouseholdId(
632	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
633	    }
634	
635	    /**
636	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
637	     * is none. The create has already cleared the hard-duplicate identity check
638	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
639	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
640	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
641	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
642	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
643	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
644	     * at the original record; owners with no postcode never match, since a shared postcode is required.
645	     *
646	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
647	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
648	     *         duplicate
649	     */
650	    private Integer findPossibleDuplicate(Owner owner) {
651	        String postcode = owner.getPostcode();
652	        if (postcode == null) {
653	            return null;
654	        }
655	        String identityKey = OwnerIdentity.identityKey(owner);
656	        String lastNameCode = Soundex.soundex(owner.getLastName());
657	        return activeOwners().stream()
658	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
659	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
660	            .filter(existing -> postcode.equals(existing.getPostcode()))
661	            .map(Owner::getId)
662	            .filter(Objects::nonNull)
663	            .min(Integer::compareTo)
664	            .orElse(null);
665	    }
666	
667	    /**
668	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
669	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
670	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
671	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
672	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
673	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
674	     * duplicate, so it is never flagged.
675	     *
676	     * @param owner           the owner being created, with telephone already normalized and
677	     *                        lastName/postcode set
678	     * @param sharesHousehold whether the request opted in to sharing a household
679	     */
680	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
681	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
682	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
683	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
684	    }
685	
686	    /**
687	     * Counts how many existing owners already live in the given city. The submitted city is compared
688	     * case-insensitively against every existing owner's stored city. The result drives both the hard
689	     * capacity rejection (see {@link #rejectCityAtCapacity}) and the {@code capacityWarning} flag.
690	     *
691	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
692	     *             run)
693	     * @return the number of existing owners whose city matches the submitted city
694	     */
695	    private long countOwnersInCity(String city) {
696	        return this.clinicService.findAllOwners().stream()
697	            .map(Owner::getCity)
698	            .filter(Objects::nonNull)
699	            .filter(city::equalsIgnoreCase)
700	            .count();
701	    }
702	
703	    /**
704	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
705	     * A city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
706	     *
707	     * @param city         the submitted city (used only to report the conflict)
708	     * @param ownersInCity the number of owners the city already holds (see {@link #countOwnersInCity})
709	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
710	     */
711	    private void rejectCityAtCapacity(String city, long ownersInCity) {
712	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
713	            throw new OwnerCityAtCapacityException(city);
714	        }
715	    }
716	
717	    /**
718	     * Resolves the effective registration date for a create, rolled onto a business day. The
719	     * supplied date is used when present, otherwise the server's current date; either way the result
720	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
721	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
722	     * stored {@code registrationDate}, the membership number's year segment and the daily
723	     * create-limit's per-day count - is judged on this adjusted date.
724	     *
725	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
726	     *                                 default to the server's current date
727	     * @return the effective registration date, guaranteed to fall on a business day
728	     */
729	    /**
730	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
731	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
732	     * adjustment; a future date cannot describe a registration that has already happened, so it is
733	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
734	     * server's current date) and any date on or before today are accepted.
735	     *
736	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
737	     *                                 omitted
738	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
739	     */
740	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
741	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
742	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
743	        }
744	    }
745	
746	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
747	        LocalDate registrationDate =
748	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
749	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
750	    }
751	
752	    /**
753	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
754	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
755	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
756	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
757	     * Too Many Requests}.
758	     *
759	     * @param registrationDate   the create's effective registration date, already rolled onto a
760	     *                           business day by {@link #effectiveRegistrationDate}
761	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
762	     *                           {@code registrationDate} equals {@code registrationDate}
763	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
764	     *                                              owner registrations
765	     */
766	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
767	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
768	            throw new OwnerDailyRegistrationLimitException(registrationDate);
769	        }
770	    }
771	
772	    /**
773	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
774	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
775	     * bulk-signup warning are judged on.
776	     *
777	     * @param registrationDate the create's effective registration date, already rolled onto a business
778	     *                         day by {@link #effectiveRegistrationDate}
779	     * @return the number of existing owners registered on that day
780	     */
781	    private long countRegisteredOn(LocalDate registrationDate) {
782	        return this.clinicService.findAllOwners().stream()
783	            .map(Owner::getRegistrationDate)
784	            .filter(registrationDate::equals)
785	            .count();
786	    }
787	}
