54	    public ClinicServiceImpl(
55	        PetRepository petRepository,
56	        VetRepository vetRepository,
57	        OwnerRepository ownerRepository,
58	        VisitRepository visitRepository,
59	        SpecialtyRepository specialtyRepository,
60	        PetTypeRepository petTypeRepository) {
