1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
28	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.util.FiscalYear.label(owner.getRegistrationDate()))")
29	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", org.springframework.samples.petclinic.util.FiscalYear.yearOf(owner.getRegistrationDate()) % 100))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
33	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
34	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
41	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
42	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
43	     */
44	    default String timezone(Owner owner) {
45	        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
46	        if (region == null) {
47	            return null;
48	        }
49	        return switch (region) {
50	            case "NSW" -> "Australia/Sydney";
51	            case "VIC" -> "Australia/Melbourne";
52	            case "QLD" -> "Australia/Brisbane";
53	            default -> null;
54	        };
55	    }
56	
57	    /**
58	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
59	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
60	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
61	     */
62	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
63	        java.time.LocalDate birthDate = owner.getBirthDate();
64	        java.time.LocalDate asOf = owner.getRegistrationDate();
65	        if (birthDate == null || asOf == null) {
66	            return null;
67	        }
68	        int years = java.time.Period.between(birthDate, asOf).getYears();
69	        if (years < 18) {
70	            return OwnerDto.AgeBandEnum.MINOR;
71	        }
72	        if (years < 65) {
73	            return OwnerDto.AgeBandEnum.ADULT;
74	        }
75	        return OwnerDto.AgeBandEnum.SENIOR;
76	    }
77	
78	    /**
79	     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
80	     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
81	     * when at least one fiscal year has elapsed since {@code registrationDate} (measured from
82	     * {@code registrationDate} to today, counting 1-July boundaries crossed).
83	     */
84	    default int membershipPoints(Owner owner) {
85	        int points = 0;
86	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
87	            points += 2;
88	        }
89	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
90	            points += 1;
91	        }
92	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
93	            points += 2;
94	        }
95	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
96	        if (registrationDate != null
97	                && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
98	                        registrationDate, java.time.LocalDate.now()) >= 1) {
99	            points += 3;
100	        }
101	        return points;
102	    }
103	
104	    /**
105	     * Reports the owner's {@code membershipLevel}. Uses the level stored on the owner when present
106	     * (as stamped on creation), otherwise falls back to the level {@linkplain #derivedMembershipLevel
107	     * derived} from its {@code membershipPoints}.
108	     */
109	    default int membershipLevel(Owner owner) {
110	        Integer stored = owner.getMembershipLevel();
111	        return stored != null ? stored : derivedMembershipLevel(owner);
112	    }
113	
114	    /**
115	     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
116	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
117	     */
118	    default int derivedMembershipLevel(Owner owner) {
119	        int points = membershipPoints(owner);
120	        if (points <= 1) {
121	            return 1;
122	        }
123	        if (points <= 3) {
124	            return 2;
125	        }
126	        if (points <= 5) {
127	            return 3;
128	        }
129	        return 4;
130	    }
131	
132	    /**
133	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
134	     * {@code PREMIUM} when {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise
135	     * {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known region
136	     * ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
137	     */
138	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
